// writes docs/sdk-reference.md from the built declaration files, so the reference never drifts from the types
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const dist = join(import.meta.dirname, '../dist')
const out = join(import.meta.dirname, '../../../docs/sdk-reference.md')
const version = JSON.parse(readFileSync(join(import.meta.dirname, '../package.json'), 'utf-8')).version
const clean = (file) => readFileSync(join(dist, file), 'utf-8').replace(/^\/\/# sourceMappingURL=.*$/m, '').replace(/^import .*$/gm, '').trim()

const sections = [
  ['Helpers', 'define.d.ts', 'Identity helpers that type a definition and return it unchanged.'],
  ['Errors', 'errors.d.ts', 'Forge matches these by `name` and `code`, so a module may bundle its own copy of the SDK.'],
  ['Types', 'types.d.ts', 'The manifest, the server context, the console client and every shape they use.'],
]

const body = sections.map(([title, file, note]) => `## ${title}\n\n${note}\n\n\`\`\`ts\n${clean(file)}\n\`\`\``).join('\n\n')
writeFileSync(out, `# @forge-dev/sdk ${version} reference\n\nGenerated by \`pnpm --filter @forge-dev/sdk reference\` from the package's declaration files. Read [module-authoring.md](module-authoring.md) first.\n\n${body}\n`)
console.log(`wrote ${out}`)
